export async function fetchSunlightData(e,t){let n=`https://api.open-meteo.com/v1/forecast?latitude=${e}&longitude=${t}&hourly=shortwave_radiation,weather_code&daily=sunrise,sunset&timezone=auto&past_days=1&forecast_days=3`,o=await fetch(n);if(!o.ok)throw Error("Failed to fetch data from Open-Meteo API");return await o.json()}export function processDataForDaytime(e,t=0){let n=e.timezone||"UTC",o=new Date().toLocaleString("en-US",{timeZone:n,hour12:!1}),a=new Date(o),i=e.daily.sunrise.map(e=>new Date(e)),r=e.daily.sunset.map(e=>new Date(e)),l=i.length-1;for(let u=0;u<r.length;u++)if(a<=r[u]){l=u;break}let s=Math.min(l+t,i.length-1),h=i[s],d=r[s],c=new Date(h);c.setMinutes(0,0,0);let w=new Date(d);w.setHours(w.getHours()+1),w.setMinutes(0,0,0);let m=[],g=[],_=[];return e.hourly.time.forEach((t,n)=>{let o=new Date(t);if(o>=c&&o<=w){let a=o.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),i=e.hourly.weather_code?e.hourly.weather_code[n]:null,r=getWeatherIcon(i);m.push(a),g.push(r),_.push(e.hourly.shortwave_radiation[n])}}),{labels:m,values:_,weatherIcons:g,date:h}}export function getTwoDayDates(e){let t=e.timezone||"UTC",n=new Date().toLocaleString("en-US",{timeZone:t,hour12:!1}),o=new Date(n),a=e.daily.sunrise.map(e=>new Date(e)),i=e.daily.sunset.map(e=>new Date(e)),r=a.length-1;for(let l=0;l<i.length;l++)if(o<=i[l]){r=l;break}return{date0:a[Math.min(r,a.length-1)],date1:a[Math.min(r+1,a.length-1)]}}function getWeatherIcon(e){return null==e?"":0===e?"☀️":1===e||2===e?"\uD83C\uDF24️":3===e?"☁️":45===e||48===e?"\uD83C\uDF2B️":e>=51&&e<=67?"\uD83C\uDF27️":e>=71&&e<=77?"❄️":e>=80&&e<=82?"\uD83C\uDF26️":85===e||86===e?"\uD83C\uDF28️":e>=95&&e<=99?"⛈️":""}